<template><div class="qan-root"><router-link to="/chat" class="qan-brand" aria-label="QGauss AI"><img src="/brand/qgauss-mark.svg" alt=""/><b>QGauss AI</b></router-link><div class="qan-heading"><span>{{nt('功能导航')}}</span><button type="button" class="qan-mobile-close" :aria-label="nt('关闭导航')" @click="$emit('close')"><ClientIcon name="close"/></button></div><label class="qan-search"><ClientIcon name="search"/><input v-model="query" type="search" :aria-label="nt('搜索入口或用途')" :placeholder="nt('搜索入口或用途')"/></label><p v-if="error" class="qan-error" role="status">{{nt(error)}}<button type="button" :disabled="loading" @click="$emit('refresh')">{{nt('重新读取')}}</button></p><div class="qan-list"><div v-if="loading&&!rows.length" class="qan-loading"><BrandLoader :size="25"/></div><NavigationTree :rows="filtered" @navigate="$emit('close')"/><p v-if="!loading&&!filtered.length" class="qan-empty">{{nt('没有匹配的入口')}}</p></div><footer><router-link v-if="canManage" to="/menus/manage" class="qan-manage" @click="$emit('close')"><ClientIcon name="layout"/><span>{{nt('导航工作台')}}</span><ClientIcon name="arrowUpRight"/></router-link><small>{{auth.user?.displayName||auth.user?.username||'QGauss'}}</small></footer></div></template>
<script setup>
import{computed,ref}from'vue';import{currentLang}from'../../i18n/index.js';import{useAuth}from'../../stores/auth.js';import{menuLabel,menuHint}from'../../lib/navigation.js';import{navigationText}from'../../i18n/navigation-messages.js';import NavigationTree from'./NavigationTree.vue';import ClientIcon from'../reference/ClientIcon.vue';import BrandLoader from'../design/BrandLoader.vue';import'./navigation.css';
const props=defineProps({rows:{type:Array,default:()=>[]},loading:Boolean,error:String,canManage:Boolean});defineEmits(['refresh','close']);const auth=useAuth(),query=ref(''),nt=value=>navigationText(currentLang.value,value),filtered=computed(()=>{const needle=query.value.trim().toLocaleLowerCase();if(!needle)return props.rows;function filter(rows){return rows.flatMap(row=>{const match=[menuLabel(row,currentLang.value),menuHint(row,currentLang.value),row.path].join(' ').toLocaleLowerCase().includes(needle),children=match?row.children||[]:filter(row.children||[]);return match||children.length?[{...row,children}]:[];});}return filter(props.rows);});
</script>
